const header=document.querySelector('#header'),hamb=document.querySelector('.hamb'),menu=document.querySelector('#menu');
const setHeader=()=>header.classList.toggle('scrolled',scrollY>18);setHeader();addEventListener('scroll',setHeader,{passive:true});
hamb.addEventListener('click',()=>{const open=menu.classList.toggle('open');hamb.setAttribute('aria-expanded',open);hamb.setAttribute('aria-label',open?'Close menu':'Open menu')});
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');hamb.setAttribute('aria-expanded','false')}));
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduce){const io=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('visible',e.isIntersecting)),{threshold:.11,rootMargin:'0px 0px -35px'});document.querySelectorAll('.reveal').forEach((el,i)=>{el.style.transitionDelay=`${Math.min(i%6,5)*.06}s`;io.observe(el)});addEventListener('scroll',()=>{const p=Math.min(scrollY*.12,80);document.querySelector('.hero-photo').style.transform=`translateY(${p}px) scale(1.08)`},{passive:true})}else document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));
const sections=[...document.querySelectorAll('main section[id]')],navLinks=[...menu.querySelectorAll('a')];const navObs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)navLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-35% 0px -58%'});sections.forEach(s=>navObs.observe(s));
const filters=[...document.querySelectorAll('.filters button')],projects=[...document.querySelectorAll('.project')];filters.forEach(btn=>btn.addEventListener('click',()=>{filters.forEach(b=>b.classList.remove('active'));btn.classList.add('active');projects.forEach(p=>{const show=btn.dataset.filter==='all'||p.dataset.category===btn.dataset.filter;p.hidden=!show})}));
const box=document.querySelector('.lightbox'),boxImg=box.querySelector('img');let active=0;function show(i){active=(i+projects.length)%projects.length;boxImg.src=projects[active].dataset.image;boxImg.alt=projects[active].querySelector('img').alt;box.classList.add('open');document.body.style.overflow='hidden';box.querySelector('.light-close').focus()}projects.forEach((p,i)=>p.addEventListener('click',()=>show(i)));function close(){box.classList.remove('open');document.body.style.overflow='';boxImg.removeAttribute('src')}box.querySelector('.light-close').addEventListener('click',close);box.querySelector('.light-prev').addEventListener('click',()=>show(active-1));box.querySelector('.light-next').addEventListener('click',()=>show(active+1));box.addEventListener('click',e=>{if(e.target===box)close()});addEventListener('keydown',e=>{if(!box.classList.contains('open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')show(active-1);if(e.key==='ArrowRight')show(active+1)});
document.querySelector('#quoteForm').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.currentTarget),msg=`Hello Dimond Engineering and Fabricating,\n\nMy name is ${d.get('name')}.\n\nLocation:\n${d.get('location')||'Not specified'}\n\nI'm interested in:\n${d.get('service')}\n\nApproximate measurements:\n${d.get('measurements')||'Not specified'}\n\nProject details:\n${d.get('message')||'Not specified'}\n\nPlease assist me with a quotation.`;window.open(`https://wa.me/263778256431?text=${encodeURIComponent(msg)}`,'_blank','noopener')});
